    {
      "name": "Fintype.card_Iic",
      "type": " {α : Type u_1} [Preorder α] [LocallyFiniteOrderBot α] (a : α) [Fintype ↑(Set.Iic a)] : Fintype.card ↑(Set.Iic a) = (Finset.Iic a).card",
      "module": "Mathlib.Order.Interval.Finset.Defs"
    },
    {
      "name": "Finset.card_Iic_prod",
      "type": " {α : Type u_1} {β : Type u_2} [Preorder α] [Preorder β] [LocallyFiniteOrderBot α] [LocallyFiniteOrderBot β] [DecidableLE (α × β)] (x : α × β) : (Finset.Iic x).card = (Finset.Iic x.1).card * (Finset.Iic x.2).card",
      "module": "Mathlib.Order.Interval.Finset.Defs"
    },
    {
      "name": "Finset.card_Iio_eq_card_Iic_sub_one",
      "type": " {α : Type u_2} [PartialOrder α] [LocallyFiniteOrderBot α] (a : α) : (Finset.Iio a).card = (Finset.Iic a).card - 1",
      "module": "Mathlib.Order.Interval.Finset.Basic"
    },
    {
      "name": "Nat.card_Iic",
      "type": " (b : ℕ) : (Finset.Iic b).card = b + 1",
      "module": "Mathlib.Order.Interval.Finset.Nat"
    },
    {
      "name": "Fin.card_Iic",
      "type": " {n : ℕ} (b : Fin n) : (Finset.Iic b).card = ↑b + 1",
      "module": "Mathlib.Order.Interval.Finset.Fin"
    },
    {
      "name": "Finsupp.card_Iic",
      "type": " {ι : Type u_1} {α : Type u_2} [AddCommMonoid α] [PartialOrder α] [IsBotZeroClass α] [OrderBot α] [LocallyFiniteOrder α] [DecidableEq ι] [DecidableEq α] (f : ι →₀ α) : (Finset.Iic f).card = ∏ i ∈ f.support, (Finset.Iic (f i)).card",
      "module": "Mathlib.Data.Finsupp.Interval"
    },
    {
      "name": "Finsupp.card_Iio",
      "type": " {ι : Type u_1} {α : Type u_2} [AddCommMonoid α] [PartialOrder α] [IsBotZeroClass α] [OrderBot α] [LocallyFiniteOrder α] [DecidableEq ι] [DecidableEq α] (f : ι →₀ α) : (Finset.Iio f).card = ∏ i ∈ f.support, (Finset.Iic (f i)).card - 1",
      "module": "Mathlib.Data.Finsupp.Interval"
    },
    {
      "name": "Finset.card_Iic_finset",
      "type": " {α : Type u_1} [DecidableEq α] {s : Finset α} : (Finset.Iic s).card = 2 ^ s.card",
      "module": "Mathlib.Data.Finset.Interval"
    },
    {
      "name": "Finset.sum_card_slice",
      "type": " {α : Type u_1} (𝒜 : Finset (Finset α)) [Fintype α] : ∑ r ≤ Fintype.card α, (𝒜.slice r).card = 𝒜.card",
      "module": "Mathlib.Data.Finset.Slice"
    },
    {
      "name": "Finset.card_shatterer_le_sum_vcDim",
      "type": " {α : Type u_1} [DecidableEq α] {𝒜 : Finset (Finset α)} [Fintype α] : 𝒜.shatterer.card ≤ ∑ k ≤ 𝒜.vcDim, (Fintype.card α).choose k",
      "module": "Mathlib.Combinatorics.SetFamily.Shatter"
    },
    {
      "name": "DFinsupp.card_Iic",
      "type": " {ι : Type u_1} {α : ι → Type u_2} [DecidableEq ι] [(i : ι) → DecidableEq (α i)] [(i : ι) → AddCommMonoid (α i)] [(i : ι) → PartialOrder (α i)] [∀ (i : ι), IsBotZeroClass (α i)] [(i : ι) → OrderBot (α i)] [(i : ι) → LocallyFiniteOrder (α i)] (f : Π₀ (i : ι), α i) : (Finset.Iic f).card = ∏ i ∈ f.support, (Finset.Iic (f i)).card",
      "module": "Mathlib.Data.DFinsupp.Interval"
    },
    {
      "name": "DFinsupp.card_Iio",
      "type": " {ι : Type u_1} {α : ι → Type u_2} [DecidableEq ι] [(i : ι) → DecidableEq (α i)] [(i : ι) → AddCommMonoid (α i)] [(i : ι) → PartialOrder (α i)] [∀ (i : ι), IsBotZeroClass (α i)] [(i : ι) → OrderBot (α i)] [(i : ι) → LocallyFiniteOrder (α i)] (f : Π₀ (i : ι), α i) : (Finset.Iio f).card = ∏ i ∈ f.support, (Finset.Iic (f i)).card - 1",
      "module": "Mathlib.Data.DFinsupp.Interval"
    }
  ]
}
